	var carg2 C.guint           // out, full, casted
	var carg3 C.GdkModifierType // out, full, casted
	var cret  C.gboolean        // return

	carg1 = (*C.char)(unsafe.Pointer(C.CString(accelerator)))
	defer C.free(unsafe.Pointer(carg1))

	cret = C.gtk_accelerator_parse(carg1, &carg2, &carg3)
	runtime.KeepAlive(accelerator)

	var acceleratorKey  uint
	var acceleratorMods gdk.ModifierType
	var goret           bool

	acceleratorKey = uint(carg2)
	acceleratorMods = gdk.ModifierType(carg3)
	if cret != 0 {
		goret = true
	}

	return acceleratorKey, acceleratorMods, goret
