// 
// ```xml
// &lt;object class="GtkStringList"&gt;
//   &lt;items&gt;
//     &lt;item translatable="yes"&gt;Factory&lt;/item&gt;
//     &lt;item translatable="yes"&gt;Home&lt;/item&gt;
