func unsafeWrapWindow(base *gobject.ObjectInstance) *WindowInstance {
	return &WindowInstance{
		WidgetInstance: WidgetInstance{
			InitiallyUnownedInstance: gobject.InitiallyUnownedInstance{
				ObjectInstance: *base,
			},
		},
	}
}

func marshalWindowInstance(p unsafe.Pointer) (any, error) {
	return unsafeWrapWindow(gobject.ValueFromNative(p).Object()), nil
}

// UnsafeWindowFromGlibNone is used to convert raw GtkWindow pointers to go while taking a reference and attaching a finalizer. This is used by the bindings internally.
func UnsafeWindowFromGlibNone(c unsafe.Pointer) Window {
	return gobject.UnsafeObjectFromGlibNone(c).(Window)
}

// UnsafeWindowFromGlibFull is used to convert raw GtkWindow pointers to go while attaching a finalizer. This is used by the bindings internally.
func UnsafeWindowFromGlibFull(c unsafe.Pointer) Window {
	return gobject.UnsafeObjectFromGlibFull(c).(Window)
}

func (w *WindowInstance) upcastToGtkWindow() *WindowInstance {
	return w
}

