//       &lt;property name="single-line-mode"&gt;True&lt;/property&gt;
//       &lt;property name="ellipsize"&gt;end&lt;/property&gt;
//       &lt;property name="width-chars"&gt;5&lt;/property&gt;
//       &lt;style&gt;
